{
  "requirements": [
    {
      "source_id": "q4",
      "quote": "Customers with an active loyalty plan receive a 10% discount on bill payments; the discount must be applied to the amount charged.",
      "requirement": "Apply 10% discount to bill payment amount when customer has active loyalty plan",
      "applies": "YES",
      "why": "Bill B3301 has loyalty_plan: 'active' (h7), so discount must be applied to the amount charged via pay_bill"
    },
    {
      "source_id": "q4",
      "quote": "You should not make up any information or knowledge not provided by the user or the tools.",
      "requirement": "Do not fabricate information; use only user-provided or tool-provided data",
      "applies": "YES",
      "why": "Always applies; all values for payment must come from h4, h5, h7"
    },
    {
      "source_id": "q5",
      "quote": "pay_bill — Pays a balance.\n    bill_id: string! — The id of the item to pay.\n    payment_method_id: string! — The payment method id.\n    amount: number! — Amount to pay.",
      "requirement": "pay_bill requires bill_id, payment_method_id, and amount parameters",
      "applies": "YES",
      "why": "User confirmed payment in h9; next move should execute pay_bill with correct parameters"
    }
  ],
  "entities": [
    {
      "refers_to": "Customer Dana Whitfield",
      "identifier": "C2044",
      "owner_or_relation": "Account holder; owns lines L2101, L2102 and bills B3301, B3302",
      "source_id": "h4"
    },
    {
      "refers_to": "Bill to pay",
      "identifier": "B3301",
      "owner_or_relation": "Belongs to customer C2044; amount_due 45.00, loyalty_plan active",
      "source_id": "h7"
    },
    {
      "refers_to": "Payment method (card)",
      "identifier": "pm_card_7781",
      "owner_or_relation": "Belongs to customer C2044; type: card",
      "source_id": "h4"
    },
    {
      "refers_to": "Phone number provided by user",
      "identifier": "555-201-3344",
      "owner_or_relation": "Matches customer C2044 Dana Whitfield",
      "source_id": "h2"
    }
  ],
  "computed_values": [
    {
      "name": "Discounted payment amount",
      "inputs": [
        {
          "value": "45.00",
          "source_id": "h7"
        },
        {
          "value": "10%",
          "source_id": "q4"
        },
        {
          "value": "active",
          "source_id": "h7"
        }
      ],
      "formula": "45.00 × (1 − 0.10) = 45.00 × 0.90",
      "result": "40.50",
      "unambiguous": true
    }
  ],
  "expected_actions": [
    {
      "must_or_must_not": "MUST",
      "action": "Call pay_bill with bill_id='B3301', payment_method_id='pm_card_7781', amount=40.50 (the discounted amount, not 45.00)"
    },
    {
      "must_or_must_not": "MUST_NOT",
      "action": "Charge the full 45.00 without applying the 10% loyalty discount"
    },
    {
      "must_or_must_not": "MUST_NOT",
      "action": "Use any payment method other than pm_card_7781 or any bill other than B3301"
    },
    {
      "must_or_must_not": "MAY",
      "action": "Confirm the payment details to the user after successful payment"
    }
  ],
  "uncertainties": []
}
